{"data":"@startuml
title Aktivitätsdiagramm
skinparam ActivityFontSize 12
skinparam ActivityDiamondFontSize 12

|Cargonaut|
start
:Registrieren/Anmelden;
:Login erfolgreich?;

split
 if (Fahrt erstellen?) then (ja)
 :Fahrt anlegen;
 else (nein)
 ' nichts tun
 endif
split again
 if (Fahrt suchen?) then (ja)
 :Fahrt suchen;
 :Fahrt auswählen;
 :Buchung anfragen;
 :Nachricht hinzufügen;
 :Warten auf Bestätigung;
 if (Buchung bestätigt?) then (ja)
 :Zahlung durchführen;
 :Fracht hinzufügen;
 :Fahrt antreten;
 :Fahrt abschließen;
 :Bewertung abgeben;
 else (nein)
 :Buchung abgelehnt;
 endif
 else (nein)
 ' nichts tun
 endif
end split

stop
@enduml","format":"svg"}
